/* ═══════════════════════════════════════════════════════
   Chat page – scoped styles
   ═══════════════════════════════════════════════════════ */

/* ── Container ── */
.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

/* ── Left Sidebar ── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: rgba(255,255,255,.08);
}

.channel-item.active {
    background: rgba(255,255,255,.15);
    border-left-color: #fff;
}

.channel-name {
    font-weight: 600;
