/* ── Container ── */
.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

/* ── Left Sidebar ── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
}

.sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    padding: 8px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: rgba(255,255,255,.08);
}

.channel-item.active {
    background: rgba(255,255,255,.15);
    border-left-color: #fff;
}

.channel-name {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    width: 100%;
    font-size: 0.75rem;
    color: #ab9bab;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

.unread-badge {
    background: #e8912d;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 1px 7px;
    min-width: 18px;
    text-align: center;
    margin-left: 4px;
}

/* ── Main Message Area ── */
.message-area {
    flex: 55;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-right: 1px solid #e1e1e1;
    transition: flex 0.2s;
}

.message-area.expanded {
    flex: 80;
    border-right: none;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
    background: #fff;
}

.message-header h4 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
}

.channel-description {
    font-size: 0.82rem;
    color: #616061;
    margin-top: 2px;
    display: block;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: 0.85rem;
}

/* ── Message Row ── */
.message-row {
    display: flex;
    align-items: flex-start;
    gap: 4px;
    padding: 6px 4px;
    border-radius: 6px;
    position: relative;
}

.message-row:hover {
    background: #f8f8f8;
}

.message-bubble {
    flex: 1;
    min-width: 0;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.9rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #9e9e9e;
}

.message-content {
    font-size: 0.92rem;
    line-height: 1.45;
    word-break: break-word;
}

/* ── Reactions ── */
.reactions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #e0e0f8;
    border-color: #aac;
}

/* ── Thread link ── */
.thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.82rem;
    cursor: pointer;
    padding: 4px 0;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Message actions (on hover) ── */
.message-actions {
    display: flex;
    gap: 2px;
    position: absolute;
    right: 4px;
    top: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,.1);
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    padding: 4px 6px;
    border-radius: 4px;
}

.action-btn:hover {
    background: #f0f0f0;
}

.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    right: 0;
    top: 110%;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 2px;
    box-shadow: 0 4px 12px rgba(0,0,0,.12);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* ── Message input ── */
.message-input-area {
    display: flex;
    gap: 8px;
    padding: 10px 16px;
    border-top: 1px solid #e8e8e8;
    background: #fff;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #1264a3;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 18px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #006449;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ── No channel placeholder ── */
.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #888;
    font-size: 1.1rem;
}

/* ── Thread Panel ── */
.thread-panel {
    width: 25%;
    min-width: 260px;
